CREATE TABLE IF NOT EXISTS schema_migration(version INTEGER PRIMARY KEY, applied_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS household(id TEXT PRIMARY KEY, settings TEXT NOT NULL, revision INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS household_member(id TEXT PRIMARY KEY, household_id TEXT NOT NULL REFERENCES household(id), name TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS auth(password_hash TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS session(id TEXT PRIMARY KEY, member_id TEXT NOT NULL REFERENCES household_member(id), expires_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS ingredient(id TEXT PRIMARY KEY, name TEXT NOT NULL UNIQUE);
CREATE TABLE IF NOT EXISTS ingredient_alias(alias TEXT PRIMARY KEY, ingredient_id TEXT NOT NULL REFERENCES ingredient(id));
CREATE TABLE IF NOT EXISTS recipe(id TEXT PRIMARY KEY, data TEXT NOT NULL, version INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS recipe_ingredient(recipe_id TEXT NOT NULL REFERENCES recipe(id) ON DELETE CASCADE, position INTEGER NOT NULL, ingredient_id TEXT NOT NULL REFERENCES ingredient(id), quantity REAL NOT NULL CHECK(quantity>0), unit TEXT NOT NULL, PRIMARY KEY(recipe_id,position));
CREATE TABLE IF NOT EXISTS recipe_version(recipe_id TEXT NOT NULL REFERENCES recipe(id) ON DELETE CASCADE, version INTEGER NOT NULL, data TEXT NOT NULL, created_at TEXT NOT NULL, PRIMARY KEY(recipe_id,version));
CREATE TABLE IF NOT EXISTS recipe_rating(recipe_id TEXT NOT NULL REFERENCES recipe(id), member_id TEXT NOT NULL REFERENCES household_member(id), rating INTEGER NOT NULL CHECK(rating BETWEEN 0 AND 5), PRIMARY KEY(recipe_id,member_id));
CREATE TABLE IF NOT EXISTS recipe_preference(recipe_id TEXT PRIMARY KEY REFERENCES recipe(id), favorite INTEGER NOT NULL DEFAULT 0, rejected INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS meal_plan(id TEXT PRIMARY KEY, week TEXT NOT NULL UNIQUE, approved INTEGER NOT NULL DEFAULT 0, version INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS planned_meal(id TEXT PRIMARY KEY, plan_id TEXT NOT NULL REFERENCES meal_plan(id) ON DELETE CASCADE, recipe_id TEXT NOT NULL REFERENCES recipe(id), day INTEGER NOT NULL CHECK(day BETWEEN 0 AND 6), meal_type TEXT NOT NULL, servings INTEGER NOT NULL CHECK(servings>0), status TEXT NOT NULL DEFAULT 'planned', locked INTEGER NOT NULL DEFAULT 0, leftover_of TEXT REFERENCES planned_meal(id) ON DELETE RESTRICT);
CREATE INDEX IF NOT EXISTS planned_meal_plan ON planned_meal(plan_id,day);
CREATE TABLE IF NOT EXISTS meal_plan_version(plan_id TEXT NOT NULL REFERENCES meal_plan(id), version INTEGER NOT NULL, data TEXT NOT NULL, created_at TEXT NOT NULL, PRIMARY KEY(plan_id,version));
CREATE TABLE IF NOT EXISTS meal_completion(meal_id TEXT PRIMARY KEY REFERENCES planned_meal(id) ON DELETE CASCADE, member_id TEXT NOT NULL REFERENCES household_member(id), completed_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS pantry_item(id TEXT PRIMARY KEY, data TEXT NOT NULL, version INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS inventory_transaction(id TEXT PRIMARY KEY, pantry_id TEXT NOT NULL, change REAL NOT NULL, created_at TEXT NOT NULL, note TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS grocery_list(id TEXT PRIMARY KEY, plan_id TEXT REFERENCES meal_plan(id), generated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS grocery_item(id TEXT PRIMARY KEY, list_id TEXT NOT NULL REFERENCES grocery_list(id), source_key TEXT NOT NULL, data TEXT NOT NULL, version INTEGER NOT NULL DEFAULT 1, UNIQUE(list_id,source_key));
CREATE TABLE IF NOT EXISTS grocery_purchase(id TEXT PRIMARY KEY, expense_id TEXT UNIQUE, data TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS price_observation(id TEXT PRIMARY KEY, ingredient_name TEXT NOT NULL, store TEXT NOT NULL, expires TEXT NOT NULL, data TEXT NOT NULL, retrieved_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS price_lookup ON price_observation(ingredient_name,expires);
CREATE TABLE IF NOT EXISTS deal_scan(id TEXT PRIMARY KEY, data TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS expense(id TEXT PRIMARY KEY, member_id TEXT NOT NULL REFERENCES household_member(id), category TEXT NOT NULL, date TEXT NOT NULL, total_cents INTEGER NOT NULL CHECK(total_cents>=0), data TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS expense_date ON expense(date,category);
CREATE TABLE IF NOT EXISTS goal(id TEXT PRIMARY KEY, data TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS reward(id TEXT PRIMARY KEY, data TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS chat_conversation(id TEXT PRIMARY KEY, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS chat_message(id TEXT PRIMARY KEY, conversation_id TEXT NOT NULL REFERENCES chat_conversation(id), role TEXT NOT NULL, content TEXT NOT NULL, data TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS assistant_tool_call(id TEXT PRIMARY KEY, message_id TEXT REFERENCES chat_message(id), name TEXT NOT NULL, args TEXT NOT NULL, status TEXT NOT NULL, result TEXT, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS scheduled_job(id TEXT PRIMARY KEY, data TEXT NOT NULL, next_run TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'idle', attempts INTEGER NOT NULL DEFAULT 0);
CREATE INDEX IF NOT EXISTS scheduled_job_due ON scheduled_job(next_run,status);
CREATE TABLE IF NOT EXISTS notification(id TEXT PRIMARY KEY, data TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS sync_event(operation_id TEXT PRIMARY KEY, member_id TEXT NOT NULL REFERENCES household_member(id), result TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS audit_log(id TEXT PRIMARY KEY, member_id TEXT, action TEXT NOT NULL, data TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS secret(name TEXT PRIMARY KEY, encrypted TEXT NOT NULL);
INSERT OR IGNORE INTO schema_migration VALUES(1,datetime('now'));

-- Additive migration: older databases retain all existing household records.
BEGIN IMMEDIATE;
CREATE TABLE IF NOT EXISTS shopping_staple(id TEXT PRIMARY KEY, source_key TEXT NOT NULL UNIQUE, data TEXT NOT NULL, version INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS leftover_batch(id TEXT PRIMARY KEY, recipe_id TEXT REFERENCES recipe(id), data TEXT NOT NULL, version INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS leftover_event(operation_id TEXT PRIMARY KEY, batch_id TEXT NOT NULL REFERENCES leftover_batch(id) ON DELETE CASCADE, member_id TEXT NOT NULL REFERENCES household_member(id), delta INTEGER NOT NULL, kind TEXT NOT NULL, result TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS leftover_event_batch ON leftover_event(batch_id,created_at);
INSERT OR IGNORE INTO schema_migration VALUES(2,datetime('now'));
COMMIT;
